import {
  Controller,
  Get,
  Post,
  Patch,
  Delete,
  Body,
  Param,
  Query,
  UseGuards,
  Req,
  HttpCode,
  HttpStatus,
} from '@nestjs/common';
import type { Request } from 'express';
import { AdminService } from './admin.service';
import { JwtAuthGuard } from '../auth/jwt-auth.guard';
import { RolesGuard } from '../common/guards/roles.guard';
import { Roles } from '../common/decorators/roles.decorator';
import { Audit } from '../common/audit/audit.decorator';
import {
  CreateAdminUserDto,
  UpdateAdminUserDto,
  UpdateUserStatusDto,
  UpdateUserPasswordDto,
  ChangeUserRoleDto,
  AuditLogQueryDto,
} from './dto/admin-users.dto';

interface RequestWithUser extends Request {
  user: { id: string };
}

@Controller('admin/users')
@UseGuards(JwtAuthGuard, RolesGuard)
@Roles('ADMIN')
export class AdminUsersController {
  constructor(private readonly adminService: AdminService) {}

  @Get()
  async listUsers() {
    return this.adminService.listUsers();
  }

  @Post()
  @Audit('USER_CREATE')
  async createUser(
    @Body() dto: CreateAdminUserDto,
    @Req() req: RequestWithUser,
  ) {
    const result = await this.adminService.createUser(dto, req.user.id);
    (req as any).auditTargetId = result.id;
    return result;
  }

  @Patch(':id')
  async updateUser(
    @Param('id') targetId: string,
    @Body() dto: UpdateAdminUserDto,
  ) {
    return this.adminService.updateUser(targetId, dto);
  }

  @Patch(':id/role')
  @Audit('ROLE_CHANGE')
  async changeRole(
    @Param('id') targetId: string,
    @Body() dto: ChangeUserRoleDto,
    @Req() req: RequestWithUser,
  ) {
    return this.adminService.changeUserRole(targetId, dto, req.user.id);
  }

  @Delete(':id')
  @HttpCode(HttpStatus.OK)
  @Audit('USER_DELETE')
  async deleteUser(
    @Param('id') targetId: string,
    @Req() req: RequestWithUser,
  ) {
    return this.adminService.softDeleteUser(targetId, req.user.id);
  }

  @Patch(':id/status')
  async setStatus(
    @Param('id') targetId: string,
    @Body() dto: UpdateUserStatusDto,
  ) {
    return this.adminService.setUserStatus(targetId, dto);
  }

  @Patch(':id/password')
  @Audit('PASSWORD_CHANGE')
  async changePassword(
    @Param('id') targetId: string,
    @Body() dto: UpdateUserPasswordDto,
  ) {
    return this.adminService.changeUserPassword(targetId, dto);
  }
}

@Controller('admin/roles')
@UseGuards(JwtAuthGuard, RolesGuard)
@Roles('ADMIN')
export class AdminRolesController {
  constructor(private readonly adminService: AdminService) {}

  @Get()
  async getRolesPermissions() {
    return this.adminService.getRolesPermissions();
  }
}

@Controller('admin/audit-log')
@UseGuards(JwtAuthGuard, RolesGuard)
@Roles('ADMIN')
export class AdminAuditLogController {
  constructor(private readonly adminService: AdminService) {}

  @Get()
  async getAuditLogs(@Query() query: AuditLogQueryDto) {
    return this.adminService.getAuditLogs(query as any);
  }
}

import { Module } from '@nestjs/common';
import { AdminService } from './admin.service';
import {
  AdminUsersController,
  AdminRolesController,
  AdminAuditLogController,
} from './admin.controller';
import { SessionsModule } from '../sessions/sessions.module';

@Module({
  imports: [SessionsModule],
  controllers: [AdminUsersController, AdminRolesController, AdminAuditLogController],
  providers: [AdminService],
})
export class AdminModule {}

import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import * as bcrypt from 'bcrypt';
import { PrismaService } from '../prisma/prisma.service';
import { SessionsService } from '../sessions/sessions.service';
import {
  CreateAdminUserDto,
  UpdateAdminUserDto,
  UpdateUserStatusDto,
  UpdateUserPasswordDto,
  ChangeUserRoleDto,
} from './dto/admin-users.dto';

type Role = 'USER' | 'ADMIN';

export const ROLES_PERMISSIONS: Record<Role, string[]> = {
  ADMIN: [
    'admin.users.view',
    'admin.users.create',
    'admin.users.edit',
    'admin.users.deactivate',
    'admin.users.password',
    'admin.roles.assign',
    'admin.roles.view',
    'admin.audit.view',
    'auth.login',
    'profile.edit',
    'profile.password',
  ],
  USER: ['auth.login', 'profile.edit', 'profile.password'],
};

@Injectable()
export class AdminService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly sessionsService: SessionsService,
  ) {}

  private async findActiveUserOrThrow(id: string) {
    const user = await this.prisma.user.findUnique({ where: { id } });
    if (!user || user.deletedAt) {
      throw new NotFoundException('User not found');
    }
    return user;
  }

  async listUsers() {
    const users = await this.prisma.user.findMany({
      where: { deletedAt: null },
      select: {
        id: true,
        email: true,
        username: true,
        emailVerified: true,
        role: true,
        active: true,
        createdAt: true,
        _count: { select: { mediaItems: true } },
      },
      orderBy: { createdAt: 'desc' },
    });
    return users.map((u) => ({
      ...u,
      mediaItemsCount: u._count.mediaItems,
      _count: undefined,
    }));
  }

  async createUser(dto: CreateAdminUserDto, requesterId: string) {
    const existing = await this.prisma.user.findFirst({
      where: { OR: [{ email: dto.email }, { username: dto.username }] },
    });
    if (existing) {
      throw new BadRequestException('Email or username already in use');
    }

    const passwordHash = await bcrypt.hash(dto.password, 12);

    const user = await this.prisma.user.create({
      data: {
        email: dto.email,
        username: dto.username,
        passwordHash,
        emailVerified: true,
        role: (dto.role ?? 'USER') as any,
        active: true,
        preferences: {
          create: {
            theme: 'dark',
            flowTimeDefault: 60,
          },
        },
      },
    });

    return {
      id: user.id,
      email: user.email,
      username: user.username,
      role: (user as any).role,
      active: (user as any).active,
    };
  }

  async updateUser(targetId: string, dto: UpdateAdminUserDto) {
    const target = await this.findActiveUserOrThrow(targetId);

    if (dto.email && dto.email !== target.email) {
      const existing = await this.prisma.user.findFirst({
        where: { email: dto.email, id: { not: targetId } },
      });
      if (existing) throw new BadRequestException('Email already in use');
    }

    if (dto.username && dto.username !== target.username) {
      const existing = await this.prisma.user.findFirst({
        where: { username: dto.username, id: { not: targetId } },
      });
      if (existing) throw new BadRequestException('Username already taken');
    }

    const data: any = {};
    if (dto.email) data.email = dto.email;
    if (dto.username) data.username = dto.username;

    const updated = await this.prisma.user.update({
      where: { id: targetId },
      data,
    });

    return {
      id: updated.id,
      email: updated.email,
      username: updated.username,
      role: (updated as any).role,
      active: (updated as any).active,
    };
  }

  async softDeleteUser(targetId: string, requesterId: string) {
    if (targetId === requesterId) {
      throw new BadRequestException(
        'Admins cannot delete their own account via this endpoint',
      );
    }
    const target = await this.findActiveUserOrThrow(targetId);

    await this.prisma.user.update({
      where: { id: targetId },
      data: { active: false, deletedAt: new Date() },
    });

    await this.sessionsService.deleteByUserId(targetId);

    return { message: `User ${target.email} deactivated and removed` };
  }

  async setUserStatus(targetId: string, dto: UpdateUserStatusDto) {
    const target = await this.findActiveUserOrThrow(targetId);

    const updated = await this.prisma.user.update({
      where: { id: targetId },
      data: { active: dto.active },
    });

    if (!dto.active) {
      await this.sessionsService.deleteByUserId(targetId);
    }

    return {
      id: updated.id,
      email: updated.email,
      active: (updated as any).active,
    };
  }

  async changeUserPassword(targetId: string, dto: UpdateUserPasswordDto) {
    const target = await this.findActiveUserOrThrow(targetId);

    const passwordHash = await bcrypt.hash(dto.newPassword, 12);

    await this.prisma.user.update({
      where: { id: targetId },
      data: {
        passwordHash,
        failedLoginAttempts: 0,
        lockedUntil: null,
      },
    });

    await this.sessionsService.deleteByUserId(targetId);

    return { message: `Password updated for ${target.email}` };
  }

  async changeUserRole(targetId: string, dto: ChangeUserRoleDto, requesterId: string) {
    if (targetId === requesterId) {
      throw new BadRequestException(
        'Admins cannot change their own role via this endpoint',
      );
    }
    const target = await this.findActiveUserOrThrow(targetId);

    const updated = await this.prisma.user.update({
      where: { id: targetId },
      data: { role: dto.role as any },
    });

    return {
      id: updated.id,
      email: updated.email,
      role: (updated as any).role,
    };
  }

  getRolesPermissions(): { roles: Record<string, { label: string; permissions: string[] }> } {
    const labels: Record<Role, string> = {
      ADMIN: 'Administrador',
      USER: 'Usuario',
    };
    const roles: Record<string, { label: string; permissions: string[] }> = {};
    for (const role of Object.keys(ROLES_PERMISSIONS) as Role[]) {
      roles[role] = {
        label: labels[role],
        permissions: ROLES_PERMISSIONS[role],
      };
    }
    return { roles };
  }

  async getAuditLogs(query: {
    page?: string;
    pageSize?: string;
    userId?: string;
    action?: string;
    from?: string;
    to?: string;
  }) {
    const page = Math.max(1, parseInt(query.page ?? '1', 10) || 1);
    const pageSize = Math.min(
      100,
      Math.max(1, parseInt(query.pageSize ?? '20', 10) || 20),
    );

    const where: any = {};
    if (query.userId) where.userId = query.userId;
    if (query.action) where.action = query.action;
    if (query.from || query.to) {
      where.timestamp = {};
      if (query.from) where.timestamp.gte = new Date(query.from);
      if (query.to) where.timestamp.lte = new Date(query.to);
    }

    const [total, items] = await this.prisma.$transaction([
      this.prisma.auditLog.count({ where }),
      this.prisma.auditLog.findMany({
        where,
        orderBy: { timestamp: 'desc' },
        skip: (page - 1) * pageSize,
        take: pageSize,
        include: { user: { select: { id: true, email: true, username: true } } },
      }),
    ]);

    return {
      total,
      page,
      pageSize,
      totalPages: Math.ceil(total / pageSize),
      items: items.map((i) => ({
        id: i.id,
        action: i.action,
        timestamp: i.timestamp,
        ipAddress: i.ipAddress,
        metadata: i.metadata,
        userId: i.userId,
        user: i.user
          ? { id: i.user.id, email: i.user.email, username: i.user.username }
          : null,
      })),
    };
  }
}

import {
  IsEmail,
  IsString,
  IsEnum,
  IsBoolean,
  IsOptional,
  MinLength,
  MaxLength,
  Matches,
} from 'class-validator';

export const ADMIN_PASSWORD_PATTERN =
  /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^A-Za-z0-9]).+$/;
export const ADMIN_PASSWORD_MESSAGE =
  'Password must contain uppercase, lowercase, a number and a symbol';

export class CreateAdminUserDto {
  @IsEmail()
  email: string;

  @IsString()
  @MinLength(3)
  @MaxLength(30)
  username: string;

  @IsString()
  @MinLength(8)
  @MaxLength(72)
  @Matches(ADMIN_PASSWORD_PATTERN, {
    message: ADMIN_PASSWORD_MESSAGE,
  })
  password: string;

  @IsOptional()
  @IsEnum(['USER', 'ADMIN'])
  role?: 'USER' | 'ADMIN';
}

export class UpdateAdminUserDto {
  @IsOptional()
  @IsEmail()
  email?: string;

  @IsOptional()
  @IsString()
  @MinLength(3)
  @MaxLength(30)
  username?: string;
}

export class UpdateUserStatusDto {
  @IsBoolean()
  active: boolean;
}

export class UpdateUserPasswordDto {
  @IsString()
  @MinLength(8)
  @MaxLength(72)
  @Matches(ADMIN_PASSWORD_PATTERN, {
    message: ADMIN_PASSWORD_MESSAGE,
  })
  newPassword: string;
}

export class ChangeUserRoleDto {
  @IsEnum(['USER', 'ADMIN'])
  role: 'USER' | 'ADMIN';
}

export class AuditLogQueryDto {
  @IsOptional()
  @IsString()
  page?: string;

  @IsOptional()
  @IsString()
  pageSize?: string;

  @IsOptional()
  @IsString()
  userId?: string;

  @IsOptional()
  @IsEnum(['LOGIN', 'LOGOUT', 'PASSWORD_CHANGE', 'USER_CREATE', 'USER_DELETE', 'ROLE_CHANGE'])
  action?: string;

  @IsOptional()
  @IsString()
  from?: string;

  @IsOptional()
  @IsString()
  to?: string;
}

import {
  Controller,
  Post,
  Body,
  UseGuards,
  Req,
  Res,
  HttpCode,
  HttpStatus,
} from '@nestjs/common';
import type { Request, Response } from 'express';
import { Throttle } from '@nestjs/throttler';
import { AuthService } from './auth.service';
import { JwtAuthGuard } from './jwt-auth.guard';
import { Audit } from '../common/audit/audit.decorator';
import { generateCsrfToken, CSRF_COOKIE } from '../common/csrf/csrf.middleware';
import {
  RegisterDto,
  LoginDto,
  WebAuthnRegisterOptionsDto,
  WebAuthnRegisterVerifyDto,
  WebAuthnLoginOptionsDto,
  WebAuthnLoginVerifyDto,
  VerifyEmailDto,
  ResendVerificationDto,
  ForgotPasswordDto,
  ResetPasswordDto,
} from './dto/auth.dto';

const COOKIE_OPTIONS = {
  httpOnly: true,
  secure: true,
  sameSite: 'none' as const,
  maxAge: 7 * 24 * 60 * 60 * 1000,
  path: '/',
};

const CSRF_COOKIE_OPTIONS = {
  httpOnly: false,
  secure: true,
  sameSite: 'none' as const,
  maxAge: 7 * 24 * 60 * 60 * 1000,
  path: '/',
};

function setCsrfCookie(res: Response) {
  res.cookie(CSRF_COOKIE, generateCsrfToken(), CSRF_COOKIE_OPTIONS);
}

// Límite estricto contra fuerza bruta (el global es más amplio).
@Throttle({ default: { limit: 10, ttl: 60000 } })
@Controller('auth')
export class AuthController {
  constructor(private readonly authService: AuthService) {}

  @Post('register')
  @HttpCode(HttpStatus.CREATED)
  async register(@Body() dto: RegisterDto) {
    return this.authService.register(dto);
  }

  @Post('verify-email')
  @HttpCode(HttpStatus.OK)
  async verifyEmail(@Body() dto: VerifyEmailDto) {
    return this.authService.verifyEmail(dto.email, dto.code);
  }

  @Post('resend-verification')
  @HttpCode(HttpStatus.OK)
  async resendVerification(@Body() dto: ResendVerificationDto) {
    return this.authService.resendVerification(dto.email);
  }

  @Post('forgot-password')
  @HttpCode(HttpStatus.OK)
  async forgotPassword(@Body() dto: ForgotPasswordDto) {
    return this.authService.forgotPassword(dto.email);
  }

  @Post('reset-password')
  @HttpCode(HttpStatus.OK)
  @Audit('PASSWORD_CHANGE')
  async resetPassword(@Body() dto: ResetPasswordDto) {
    return this.authService.resetPassword(dto.token, dto.newPassword);
  }

  @Post('login')
  @HttpCode(HttpStatus.OK)
  @Audit('LOGIN')
  async login(
    @Body() dto: LoginDto,
    @Req() req: Request,
    @Res({ passthrough: true }) res: Response,
  ) {
    const session = await this.authService.login(dto, req);
    (req as any).auditTargetId = (req as any).auditUserId;
    res.cookie('Authentication', session.accessToken, COOKIE_OPTIONS);
    setCsrfCookie(res);
    return { success: true, token: session.accessToken };
  }

  @Post('logout')
  @UseGuards(JwtAuthGuard)
  @HttpCode(HttpStatus.OK)
  @Audit('LOGOUT')
  async logout(
    @Req() req: Request & { user: { id: string } },
    @Res({ passthrough: true }) res: Response,
  ) {
    (req as any).auditTargetId = req.user.id;
    await this.authService.logout((req as any).user.id);
    res.clearCookie('Authentication', {
      httpOnly: true,
      secure: true,
      sameSite: 'none',
      path: '/',
    });
    return { success: true };
  }

  @Post('webauthn/register/options')
  @HttpCode(HttpStatus.OK)
  async webAuthnRegisterOptions(@Body() dto: WebAuthnRegisterOptionsDto) {
    return this.authService.generateWebAuthnRegisterOptions(dto.email);
  }

  @Post('webauthn/register/verify')
  @HttpCode(HttpStatus.OK)
  async webAuthnRegisterVerify(@Body() dto: WebAuthnRegisterVerifyDto) {
    return this.authService.verifyWebAuthnRegister(dto);
  }

  @Post('webauthn/login/options')
  @HttpCode(HttpStatus.OK)
  async webAuthnLoginOptions(@Body() dto: WebAuthnLoginOptionsDto) {
    return this.authService.generateWebAuthnLoginOptions(dto.email);
  }

  @Post('webauthn/login/verify')
  @HttpCode(HttpStatus.OK)
  async webAuthnLoginVerify(
    @Body() dto: WebAuthnLoginVerifyDto,
    @Req() req: Request,
    @Res({ passthrough: true }) res: Response,
  ) {
    const session = await this.authService.verifyWebAuthnLogin(dto, req);
    res.cookie('Authentication', session.accessToken, COOKIE_OPTIONS);
    setCsrfCookie(res);
    return { success: true, token: session.accessToken };
  }
}

import {
  Injectable,
  BadRequestException,
  UnauthorizedException,
  Logger,
} from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { PrismaService } from '../prisma/prisma.service';
import { SessionsService } from '../sessions/sessions.service';
import { MailService } from '../mail/mail.service';
import {
  generateRegistrationOptions,
  verifyRegistrationResponse,
  generateAuthenticationOptions,
  verifyAuthenticationResponse,
} from '@simplewebauthn/server';
import {
  RegisterDto,
  LoginDto,
  WebAuthnRegisterVerifyDto,
  WebAuthnLoginVerifyDto,
} from './dto/auth.dto';
import { createHash, randomBytes, randomUUID } from 'crypto';
import * as bcrypt from 'bcrypt';
import type { Request } from 'express';

const MAX_FAILED_ATTEMPTS = 5;
const LOCK_DURATION_MS = 15 * 60 * 1000; // 15 minutos

@Injectable()
export class AuthService {
  private readonly logger = new Logger(AuthService.name);
  private readonly rpID: string;
  private readonly rpName: string;
  private readonly expectedOrigin: string;

  constructor(
    private readonly prisma: PrismaService,
    private readonly jwtService: JwtService,
    private readonly sessionsService: SessionsService,
    private readonly mailService: MailService,
  ) {
    this.rpID = process.env.RP_ID ?? 'localhost';
    this.rpName = process.env.RP_NAME ?? 'CEOSMOS';
    this.expectedOrigin =
      process.env.FRONTEND_ORIGIN ?? 'http://localhost:4200';
  }

  async register(dto: RegisterDto): Promise<{ message: string }> {
    console.log(`[AuthService] Registering user with email: ${dto.email}`);
    const existing = await this.prisma.user.findFirst({
      where: { OR: [{ email: dto.email }, { username: dto.username }] },
    });
    if (existing) {
      // Unverified account with same email: resend code instead of rejecting
      if (existing.email === dto.email && !existing.emailVerified) {
        await this.resendVerification(dto.email);
        return { message: 'Verification email resent. Check your inbox.' };
      }
      console.error(`[AuthService] Registration failed: Email or username already in use (${dto.email}, ${dto.username})`);
      throw new BadRequestException('Email or username already in use');
    }

    const passwordHash = await bcrypt.hash(dto.password, 12);

    const user = await this.prisma.user.create({
      data: {
        email: dto.email,
        username: dto.username,
        passwordHash,
        emailVerified: false,
        preferences: {
          create: {
            theme: 'dark',
            flowTimeDefault: 60,
          },
        },
      },
    });

    const rawCode = randomBytes(3).toString('hex').toUpperCase();
    const hashedCode = createHash('sha256').update(rawCode).digest('hex');

    await this.prisma.emailToken.create({
      data: {
        userId: user.id,
        code: hashedCode,
        type: 'VERIFY_EMAIL',
        expiresAt: new Date(Date.now() + 15 * 60 * 1000),
      },
    });

    try {
      await this.mailService.sendVerificationEmail(user.email, rawCode);
    } catch (mailError) {
      console.error('[AuthService] Mail failed during register, continuing', mailError);
    }

    console.log(`[AuthService] User registered successfully: ${user.email}`);

    return { message: 'User created. Check your email for the verification code.' };
  }

  async login(
    dto: LoginDto,
    req: Request,
  ): Promise<{ accessToken: string }> {
    console.log(`[AuthService] Login attempt for email: ${dto.email}`);
    const user = await this.prisma.user.findUnique({
      where: { email: dto.email },
    });

    if (!user || !user.passwordHash) {
      console.error(`[AuthService] Login failed: Invalid credentials for ${dto.email}`);
      throw new UnauthorizedException('Invalid credentials');
    }

    if (!user.active) {
      throw new UnauthorizedException('Account is disabled. Contact an administrator.');
    }

    if (user.lockedUntil && user.lockedUntil > new Date()) {
      const minutesLeft = Math.ceil((user.lockedUntil.getTime() - Date.now()) / 60000);
      throw new UnauthorizedException(
        `Account temporarily locked due to too many failed attempts. Try again in ${minutesLeft} minute(s).`,
      );
    }

    if (!user.emailVerified) {
      console.error(`[AuthService] Login failed: Email not verified for ${dto.email}`);
      throw new UnauthorizedException('Email not verified');
    }

    const isValid = await bcrypt.compare(dto.password, user.passwordHash);
    if (!isValid) {
      console.error(`[AuthService] Login failed: Password mismatch for ${dto.email}`);
      const newFailedCount = user.failedLoginAttempts + 1;
      const shouldLock = newFailedCount >= MAX_FAILED_ATTEMPTS;

      await this.prisma.user.update({
        where: { id: user.id },
        data: {
          failedLoginAttempts: shouldLock ? 0 : newFailedCount,
          lockedUntil: shouldLock ? new Date(Date.now() + LOCK_DURATION_MS) : user.lockedUntil,
        },
      });

      if (shouldLock) {
        throw new UnauthorizedException(
          `Account locked for 15 minutes due to ${MAX_FAILED_ATTEMPTS} failed attempts.`,
        );
      }

      const attemptsLeft = MAX_FAILED_ATTEMPTS - newFailedCount;
      throw new UnauthorizedException(
        `Invalid credentials. ${attemptsLeft} attempt(s) remaining before lock.`,
      );
    }

    await this.prisma.user.update({
      where: { id: user.id },
      data: { failedLoginAttempts: 0, lockedUntil: null },
    });

    (req as any).auditUserId = user.id;

    console.log(`[AuthService] User logged in successfully: ${dto.email}`);
    return this.buildJwtSession(user.id, req);
  }

  async logout(userId: string): Promise<{ message: string }> {
    await this.sessionsService.deleteByUserId(userId);
    return { message: 'Logged out successfully' };
  }

  async verifyEmail(
    email: string,
    rawCode: string,
  ): Promise<{ message: string }> {
    const user = await this.prisma.user.findUnique({ where: { email } });
    if (!user) throw new BadRequestException('User not found');

    const hashedCode = createHash('sha256').update(rawCode).digest('hex');

    const token = await this.prisma.emailToken.findFirst({
      where: {
        userId: user.id,
        type: 'VERIFY_EMAIL',
        code: hashedCode,
        used: false,
        expiresAt: { gt: new Date() },
      },
    });

    if (!token) throw new BadRequestException('Invalid or expired code');

    await this.prisma.$transaction([
      this.prisma.emailToken.update({
        where: { id: token.id },
        data: { used: true },
      }),
      this.prisma.user.update({
        where: { id: user.id },
        data: { emailVerified: true },
      }),
    ]);

    return { message: 'Email verified successfully' };
  }

  async resendVerification(email: string): Promise<{ message: string }> {
    const user = await this.prisma.user.findUnique({ where: { email } });
    if (!user) throw new BadRequestException('User not found');
    if (user.emailVerified) throw new BadRequestException('Email already verified');

    const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);
    const recentTokensCount = await this.prisma.emailToken.count({
      where: {
        userId: user.id,
        type: 'VERIFY_EMAIL',
        createdAt: { gt: oneHourAgo },
      },
    });

    if (recentTokensCount >= 3) {
      throw new BadRequestException('Rate limit exceeded: max 3 requests per hour');
    }

    await this.prisma.emailToken.updateMany({
      where: { userId: user.id, type: 'VERIFY_EMAIL', used: false },
      data: { used: true },
    });

    const rawCode = randomBytes(3).toString('hex').toUpperCase();
    const hashedCode = createHash('sha256').update(rawCode).digest('hex');

    await this.prisma.emailToken.create({
      data: {
        userId: user.id,
        code: hashedCode,
        type: 'VERIFY_EMAIL',
        expiresAt: new Date(Date.now() + 15 * 60 * 1000),
      },
    });

    try {
      await this.mailService.sendVerificationEmail(user.email, rawCode);
    } catch (mailError) {
      console.error('[AuthService] Mail failed during resendVerification, continuing', mailError);
    }

    return { message: 'Verification code resent successfully' };
  }

  async forgotPassword(email: string): Promise<{ message: string }> {
    const user = await this.prisma.user.findUnique({ where: { email } });
    if (!user) {
      return { message: 'If the email exists, a password reset link has been sent.' };
    }

    const rawToken = `${randomUUID()}-${Date.now()}`;
    const hashedToken = createHash('sha256').update(rawToken).digest('hex');

    await this.prisma.emailToken.updateMany({
      where: { userId: user.id, type: 'RESET_PASSWORD', used: false },
      data: { used: true },
    });

    await this.prisma.emailToken.create({
      data: {
        userId: user.id,
        code: hashedToken,
        type: 'RESET_PASSWORD',
        expiresAt: new Date(Date.now() + 60 * 60 * 1000),
      },
    });

    await this.mailService.sendPasswordResetEmail(user.email, rawToken);

    return { message: 'If the email exists, a password reset link has been sent.' };
  }

  async resetPassword(token: string, newPassword: string): Promise<{ message: string }> {
    const hashedToken = createHash('sha256').update(token).digest('hex');
    
    const tokenRecord = await this.prisma.emailToken.findFirst({
      where: {
        code: hashedToken,
        type: 'RESET_PASSWORD',
        used: false,
        expiresAt: { gt: new Date() },
      },
    });

    if (!tokenRecord) {
      throw new BadRequestException('Invalid or expired token');
    }

    const passwordHash = await bcrypt.hash(newPassword, 12);

    await this.prisma.$transaction([
      this.prisma.user.update({
        where: { id: tokenRecord.userId },
        data: { passwordHash },
      }),
      this.prisma.emailToken.update({
        where: { id: tokenRecord.id },
        data: { used: true },
      }),
    ]);

    await this.sessionsService.deleteByUserId(tokenRecord.userId);

    return { message: 'Password reset successfully' };
  }

  async generateWebAuthnRegisterOptions(email: string) {
    const user = await this.prisma.user.findUnique({ where: { email } });
    if (!user) throw new BadRequestException('User not found');

    const existingPasskeys = await this.prisma.passkey.findMany({
      where: { userId: user.id },
    });

    const options = await generateRegistrationOptions({
      rpName: this.rpName,
      rpID: this.rpID,
      userID: new Uint8Array(Buffer.from(user.id, 'utf-8')),
      userName: user.email,
      excludeCredentials: existingPasskeys.map((p) => ({
        id: p.credentialId,
        type: 'public-key' as const,
      })),
      authenticatorSelection: {
        residentKey: 'required',
        userVerification: 'preferred',
      },
    });

    return options;
  }

  async verifyWebAuthnRegister(dto: WebAuthnRegisterVerifyDto) {
    const user = await this.prisma.user.findUnique({
      where: { email: dto.email },
    });
    if (!user) throw new BadRequestException('User not found');

    this.logger.log(`[WebAuthn Register] rpID: "${this.rpID}"`);
    this.logger.log(`[WebAuthn Register] expectedOrigin: "${this.expectedOrigin}"`);
    this.logger.log(`[WebAuthn Register] challenge: "${dto.challenge}"`);
    this.logger.log(`[WebAuthn Register] response.id: "${(dto.response as any)?.id}"`);

    let verification: any;
    try {
      verification = await verifyRegistrationResponse({
        response: dto.response as any,
        expectedChallenge: dto.challenge,
        expectedOrigin: this.expectedOrigin,
        expectedRPID: this.rpID,
        requireUserVerification: false,
      });
      this.logger.log(`[WebAuthn Register] verified: ${verification.verified}`);
    } catch (error: any) {
      this.logger.error(`[WebAuthn Register] verifyRegistrationResponse threw: ${error.message}`);
      throw error;
    }

    if (!verification.verified || !verification.registrationInfo) {
      throw new BadRequestException('WebAuthn registration verification failed');
    }

    const { credential, credentialDeviceType, credentialBackedUp } =
      verification.registrationInfo;

    await this.prisma.passkey.create({
      data: {
        credentialId: credential.id,
        userId: user.id,
        webAuthnUserId: Buffer.from(user.id, 'utf-8').toString('base64url'),
        publicKey: Buffer.from(credential.publicKey),
        counter: BigInt(credential.counter),
        deviceType: credentialDeviceType,
        backedUp: credentialBackedUp,
        transports: (dto.response as any)?.response?.transports ?? [],
      },
    });

    return { verified: true };
  }

  async generateWebAuthnLoginOptions(email: string) {
    const user = await this.prisma.user.findUnique({ where: { email } });
    if (!user) throw new BadRequestException('User not found');

    const passkeys = await this.prisma.passkey.findMany({
      where: { userId: user.id },
    });

    if (passkeys.length === 0) {
      throw new BadRequestException('No passkeys registered for this user');
    }

    const options = await generateAuthenticationOptions({
      rpID: this.rpID,
      allowCredentials: passkeys.map((p) => ({
        id: p.credentialId,
        type: 'public-key' as const,
      })),
      userVerification: 'preferred',
    });

    return options;
  }

  async verifyWebAuthnLogin(dto: WebAuthnLoginVerifyDto, req: Request) {
    const user = await this.prisma.user.findUnique({
      where: { email: dto.email },
    });
    if (!user) throw new BadRequestException('User not found');

    const credentialId = (dto.response as any).id as string;
    const passkey = await this.prisma.passkey.findUnique({
      where: { credentialId },
    });

    if (!passkey || passkey.userId !== user.id) {
      throw new UnauthorizedException('Invalid credential');
    }

    const verification = await verifyAuthenticationResponse({
      response: dto.response as any,
      expectedChallenge: dto.challenge,
      expectedOrigin: this.expectedOrigin,
      expectedRPID: this.rpID,
      credential: {
        id: passkey.credentialId,
        publicKey: new Uint8Array(passkey.publicKey),
        counter: Number(passkey.counter),
        transports: passkey.transports as any,
      },
      requireUserVerification: false,
    });

    if (!verification.verified) {
      throw new UnauthorizedException('WebAuthn authentication failed');
    }

    await this.prisma.passkey.update({
      where: { credentialId: passkey.credentialId },
      data: { counter: BigInt(verification.authenticationInfo.newCounter) },
    });

    return this.buildJwtSession(user.id, req);
  }

  private async buildJwtSession(
    userId: string,
    req: Request,
  ): Promise<{ accessToken: string }> {
    const rawToken = await this.sessionsService.createSession(userId, req);
    const accessToken = this.jwtService.sign({ userId, sessionToken: rawToken });
    return { accessToken };
  }
}

import {
