// Política de contraseña segura: mínimo 8 caracteres, mayúscula, minúscula,
// número y símbolo. Se comparte entre registro y cambio de contraseña.
export const PASSWORD_PATTERN = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^A-Za-z0-9]).+$/;
export const PASSWORD_MESSAGE =
  'Password must contain uppercase, lowercase, a number and a symbol';

export class RegisterDto {
  @IsEmail()
  email: string;

  @IsString()
  @MinLength(3)
  @MaxLength(30)
  username: string;

  @IsString()
  @MinLength(8)
  @MaxLength(72)
  @Matches(PASSWORD_PATTERN, {
    message: PASSWORD_MESSAGE,
  })
  password: string;
}

export class LoginDto {
  @IsEmail()
  email: string;

  @IsString()
  @MinLength(1)
  password: string;
}

export class WebAuthnRegisterOptionsDto {
  @IsEmail()
  email: string;
}

export class WebAuthnRegisterVerifyDto {
  @IsEmail()
  email: string;

  @IsString()
  challenge: string;

  @IsObject()
  response: Record<string, unknown>;
}

export class WebAuthnLoginOptionsDto {
  @IsEmail()
  email: string;
}

export class WebAuthnLoginVerifyDto {
  @IsEmail()
  email: string;

  @IsString()
  challenge: string;

  @IsObject()
  response: Record<string, unknown>;
}

export class VerifyEmailDto {
  @IsEmail()
  email: string;

  @IsString()
  @MinLength(6)
  @MaxLength(6)
  code: string;
}

export class ResendVerificationDto {
  @IsEmail()
  email: string;
}

export class ForgotPasswordDto {
  @IsEmail()
  email: string;
}

export class ResetPasswordDto {
  @IsString()
  @MinLength(1)
  token: string;

  @IsString()
  @MinLength(8)
  @MaxLength(72)
  @Matches(PASSWORD_PATTERN, {
    message: PASSWORD_MESSAGE,
  })
  newPassword: string;
}

import { Injectable, ExecutionContext, UnauthorizedException } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { Observable } from 'rxjs';

@Injectable()
export class JwtAuthGuard extends AuthGuard('jwt') {
  canActivate(
    context: ExecutionContext,
  ): boolean | Promise<boolean> | Observable<boolean> {
    return super.canActivate(context);
  }

  handleRequest<TUser = any>(err: any, user: TUser, info: any): TUser {
    if (err || !user) {
      throw err ?? new UnauthorizedException(info?.message ?? 'Unauthorized');
    }
    return user;
  }
}

import { Injectable, UnauthorizedException } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { createHash } from 'crypto';
import { PrismaService } from '../prisma/prisma.service';
import { User } from '@prisma/client';

interface JwtPayload {
  userId: string;
  sessionToken: string;
}

@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor(private readonly prisma: PrismaService) {
    super({
      jwtFromRequest: ExtractJwt.fromExtractors([
        ExtractJwt.fromAuthHeaderAsBearerToken(),
        (request: any) => request?.cookies?.Authentication ?? null,
      ]),
      ignoreExpiration: false,
      secretOrKey: process.env.JWT_SECRET ?? 'changeme',
    });
  }

  async validate(payload: JwtPayload): Promise<User> {
    const hashedToken = createHash('sha256')
      .update(payload.sessionToken)
      .digest('hex');

    const session = await this.prisma.session.findUnique({
      where: { token: hashedToken },
    });

    if (!session || session.expiresAt < new Date()) {
      throw new UnauthorizedException('Session not found or expired');
    }

    const user = await this.prisma.user.findUnique({
      where: { id: payload.userId },
    });

    if (!user) {
      throw new UnauthorizedException('User not found');
    }

    return user;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import type { Request } from 'express';

export type AuditAction =
  | 'LOGIN'
  | 'LOGOUT'
  | 'PASSWORD_CHANGE'
  | 'USER_CREATE'
  | 'USER_DELETE'
  | 'ROLE_CHANGE';

export const AUDIT_ACTIONS: AuditAction[] = [
  'LOGIN',
  'LOGOUT',
  'PASSWORD_CHANGE',
  'USER_CREATE',
  'USER_DELETE',
  'ROLE_CHANGE',
];

@Injectable()
export class AuditLogService {
  private readonly logger = new Logger(AuditLogService.name);

  constructor(private readonly prisma: PrismaService) {}

  /**
   * Resuelve la IP real de la request considerando proxies (X-Forwarded-For).
   */
  getClientIp(req?: Request): string | null {
    if (!req) return null;
    const forwarded = req.headers['x-forwarded-for'];
    if (forwarded) {
      const first = (Array.isArray(forwarded) ? forwarded[0] : forwarded).split(',')[0].trim();
      if (first) return first;
    }
    return req.ip ?? null;
  }

  async log(
    action: AuditAction,
    userId: string | null,
    req?: Request,
    metadata?: Record<string, unknown>,
  ): Promise<void> {
    try {
      await this.prisma.auditLog.create({
        data: {
          userId,
          action,
          ipAddress: this.getClientIp(req),
          metadata: (metadata ?? null) as any,
        },
      });
    } catch (error) {
      this.logger.error(`Failed to write audit log (${action}): ${(error as Error).message}`);
    }
  }

  async query(filters: {
    page?: number;
    pageSize?: number;
    userId?: string;
    action?: AuditAction;
    from?: string;
    to?: string;
  }) {
    const page = Math.max(1, filters.page ?? 1);
    const pageSize = Math.min(100, Math.max(1, filters.pageSize ?? 20));

    const where: any = {};
    if (filters.userId) where.userId = filters.userId;
    if (filters.action) where.action = filters.action;
    if (filters.from || filters.to) {
      where.timestamp = {};
      if (filters.from) where.timestamp.gte = new Date(filters.from);
      if (filters.to) where.timestamp.lte = new Date(filters.to);
    }

    const [total, items] = await this.prisma.$transaction([
      this.prisma.auditLog.count({ where }),
      this.prisma.auditLog.findMany({
        where,
        orderBy: { timestamp: 'desc' },
        skip: (page - 1) * pageSize,
        take: pageSize,
        include: { user: { select: { id: true, email: true, username: true } } },
      }),
    ]);

    return {
      total,
      page,
      pageSize,
      totalPages: Math.ceil(total / pageSize),
      items: items.map((i) => ({
        id: i.id,
        action: i.action,
        timestamp: i.timestamp,
        ipAddress: i.ipAddress,
        metadata: i.metadata,
        userId: i.userId,
        user: i.user
          ? { id: i.user.id, email: i.user.email, username: i.user.username }
          : null,
      })),
    };
  }
}

import { SetMetadata } from '@nestjs/common';
import { AuditAction } from './audit-log.service';

export const AUDIT_ACTION_KEY = 'audit_action';
export const Audit = (action: AuditAction) => SetMetadata(AUDIT_ACTION_KEY, action);

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
  Logger,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { Observable } from 'rxjs';
import { tap } from 'rxjs/operators';
import { AuditLogService, AuditAction } from './audit-log.service';
import { AUDIT_ACTION_KEY } from './audit.decorator';
import type { Request } from 'express';

@Injectable()
export class AuditInterceptor implements NestInterceptor {
  private readonly logger = new Logger(AuditInterceptor.name);

  constructor(
    private readonly reflector: Reflector,
    private readonly auditLogService: AuditLogService,
  ) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const action = this.reflector.get<AuditAction>(
      AUDIT_ACTION_KEY,
      context.getHandler(),
    );

    if (!action) {
      return next.handle();
    }

    const req = context.switchToHttp().getRequest<Request & { user?: { id?: string }; auditUserId?: string }>();

    return next.handle().pipe(
      tap(() => {
        const userId = req.user?.id ?? req.auditUserId ?? null;
        const metadata = {
          method: req.method,
          path: req.route?.path ?? req.originalUrl,
          targetId: (req as any).auditTargetId ?? (req.params as Record<string, string>)?.id ?? null,
        };
        this.auditLogService.log(action, userId, req, metadata);
      }),
    );
  }
}

import { Request, Response, NextFunction } from 'express';

// Ruta que emiten la cookie de sesión y el token CSRF (públicas, pre-autenticación).
const CSRF_EXEMPT_ROUTES = [
  '/api/auth/login',
  '/api/auth/register',
  '/api/auth/verify-email',
  '/api/auth/resend-verification',
  '/api/auth/forgot-password',
  '/api/auth/reset-password',
  '/api/auth/webauthn/login/options',
  '/api/auth/webauthn/login/verify',
  '/api/auth/webauthn/register/options',
  '/api/auth/webauthn/register/verify',
];

const MUTATING_METHODS = ['POST', 'PUT', 'PATCH', 'DELETE'];

export const CSRF_COOKIE = 'csrfToken';
export const CSRF_HEADER = 'x-csrf-token';

export function generateCsrfToken(): string {
  return require('crypto').randomBytes(32).toString('hex');
}

export function csrfMiddleware(req: Request, res: Response, next: NextFunction) {
  const method = (req.method ?? '').toUpperCase();

  if (!MUTATING_METHODS.includes(method)) {
    return next();
  }

  if (CSRF_EXEMPT_ROUTES.includes(req.path)) {
    return next();
  }

  // CSRF solo afecta a la autenticación por cookie (el navegador la envía sola).
  // Un cliente nativo que se autentica con «Authorization: Bearer» y no envía la
  // cookie de sesión no es atacable por CSRF; se le exime de la doble cookie.
  const bearer = /^Bearer\s+\S+$/i.test(req.headers.authorization ?? '');
  const sessionCookie = (req.cookies ?? {})['Authentication'];
  if (bearer && !sessionCookie) {
    return next();
  }

  const cookieToken = (req.cookies ?? {})[CSRF_COOKIE] as string | undefined;
  const headerToken = req.headers[CSRF_HEADER] as string | undefined;

  if (!cookieToken || !headerToken || cookieToken !== headerToken) {
    return res.status(403).json({
      statusCode: 403,
      message: 'CSRF token mismatch or missing',
      error: 'Forbidden',
    });
  }

  return next();
}

import {
  ExceptionFilter,
  Catch,
  ArgumentsHost,
  HttpException,
  HttpStatus,
} from '@nestjs/common';
import type { Response } from 'express';

@Catch(HttpException)
export class HttpExceptionFilter implements ExceptionFilter {
  catch(exception: HttpException, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse<Response>();
    const status = exception.getStatus();
    const exceptionResponse = exception.getResponse();

    const message =
      typeof exceptionResponse === 'object' && 'message' in exceptionResponse
        ? (exceptionResponse as any).message
        : exception.message;

    response.status(status).json({
      statusCode: status,
      message,
      error: HttpStatus[status] ?? 'Error',
    });
  }
}

import {
  Injectable,
  CanActivate,
  ExecutionContext,
  ForbiddenException,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { ROLES_KEY, Role } from '../decorators/roles.decorator';

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private readonly reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const requiredRoles = this.reflector.getAllAndOverride<Role[]>(ROLES_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);

    // Si la ruta no tiene @Roles(), deja pasar (JwtAuthGuard ya validó el JWT)
    if (!requiredRoles || requiredRoles.length === 0) {
      return true;
    }

    const { user } = context.switchToHttp().getRequest();

    if (!user || !requiredRoles.includes((user as any).role)) {
      throw new ForbiddenException(
        'You do not have permission to access this resource',
      );
    }

    return true;
  }
}

import {
  Body,
  ConflictException,
  Controller,
  Delete,
  Get,
  HttpCode,
  HttpStatus,
  NotFoundException,
  Param,
  ParseUUIDPipe,
  Patch,
  Post,
  Req,
  UseGuards,
} from '@nestjs/common';
import { Prisma } from '@prisma/client';
import type { Request } from 'express';
import { JwtAuthGuard } from '../auth/jwt-auth.guard';
import { PrismaService } from '../prisma/prisma.service';
import { CreateDeviceDto, UpdateDeviceDto } from './dto/devices.dto';

interface RequestWithUser extends Request {
  user: { id: string };
}

/** Dispositivos vinculados (wearable por TCP/IP o BLE) del usuario autenticado. */
@Controller('devices')
@UseGuards(JwtAuthGuard)
export class DevicesController {
  constructor(private readonly prisma: PrismaService) {}

  @Get()
  list(@Req() req: RequestWithUser) {
    return this.prisma.linkedDevice.findMany({
      where: { userId: req.user.id },
      orderBy: { createdAt: 'asc' },
    });
  }

  @Post()
  async create(@Req() req: RequestWithUser, @Body() dto: CreateDeviceDto) {
    try {
      return await this.prisma.linkedDevice.create({
        data: {
          userId: req.user.id,
          name: dto.name.trim(),
          type: dto.type,
          transport: dto.transport,
          address: dto.address,
          configuration: dto.configuration as Prisma.InputJsonValue | undefined,
        },
      });
    } catch (e) {
      if (e instanceof Prisma.PrismaClientKnownRequestError && e.code === 'P2002') {
        throw new ConflictException('Ese dispositivo ya está vinculado.');
      }
      throw e;
    }
  }

  @Patch(':id')
  async update(
    @Req() req: RequestWithUser,
    @Param('id', ParseUUIDPipe) id: string,
    @Body() dto: UpdateDeviceDto,
  ) {
    // El filtro por userId evita modificar dispositivos ajenos (404, no 403).
    const result = await this.prisma.linkedDevice.updateMany({
      where: { id, userId: req.user.id },
      data: {
        ...(dto.name !== undefined && { name: dto.name.trim() }),
        ...(dto.address !== undefined && { address: dto.address }),
        ...(dto.configuration !== undefined && {
          configuration: dto.configuration as Prisma.InputJsonValue,
        }),
        ...(dto.seen && { lastSeenAt: new Date() }),
      },
    });
    if (result.count === 0) throw new NotFoundException('Dispositivo no encontrado');
    return this.prisma.linkedDevice.findUnique({ where: { id } });
  }

  @Delete(':id')
  @HttpCode(HttpStatus.NO_CONTENT)
  async remove(@Req() req: RequestWithUser, @Param('id', ParseUUIDPipe) id: string) {
    const result = await this.prisma.linkedDevice.deleteMany({
      where: { id, userId: req.user.id },
    });
    if (result.count === 0) throw new NotFoundException('Dispositivo no encontrado');
  }
}

import { IsIn, IsObject, IsOptional, IsString, Length, Matches } from 'class-validator';

// host:puerto (IPv4 o nombre) para TCP; dirección MAC para BLE.
export const DEVICE_ADDRESS =
  /^([A-Za-z0-9.-]{1,63}:\d{2,5}|([0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2})$/;

export class CreateDeviceDto {
  @IsString()
  @Length(1, 40)
  name: string;

  @IsIn(['WEARABLE', 'TV'])
  type: 'WEARABLE' | 'TV';

  @IsIn(['TCP', 'BLE'])
  transport: 'TCP' | 'BLE';

  @Matches(DEVICE_ADDRESS, { message: 'Dirección inválida (host:puerto o MAC)' })
  address: string;

  @IsOptional()
  @IsObject()
  configuration?: Record<string, unknown>;
}

export class UpdateDeviceDto {
  @IsOptional()
  @IsString()
  @Length(1, 40)
  name?: string;

  @IsOptional()
  @Matches(DEVICE_ADDRESS, { message: 'Dirección inválida (host:puerto o MAC)' })
  address?: string;

  @IsOptional()
  @IsObject()
  configuration?: Record<string, unknown>;

  /** La app lo envía al recibir datos del dispositivo. */
  @IsOptional()
  @IsIn([true])
  seen?: true;
}

import {
  BadRequestException,
  Controller,
  Delete,
  Get,
  HttpCode,
  HttpStatus,
  Param,
  Put,
  Req,
  UseGuards,
} from '@nestjs/common';
import type { Request } from 'express';
import { JwtAuthGuard } from '../auth/jwt-auth.guard';
import { PrismaService } from '../prisma/prisma.service';
import { CONTENT_KEY } from '../focus-sessions/dto/focus-sessions.dto';

interface RequestWithUser extends Request {
  user: { id: string };
}

/** Favoritos del usuario: claves del catálogo incluido o "media:<id>". */
@Controller('favorites')
@UseGuards(JwtAuthGuard)
export class FavoritesController {
  constructor(private readonly prisma: PrismaService) {}

  private key(value: string) {
    if (!CONTENT_KEY.test(value)) throw new BadRequestException('contentKey inválido');
    return value;
  }

  @Get()
  async list(@Req() req: RequestWithUser) {
    const rows = await this.prisma.favorite.findMany({
      where: { userId: req.user.id },
      orderBy: { createdAt: 'desc' },
      select: { contentKey: true, createdAt: true },
    });
    return rows;
  }

  /** Idempotente: marcar dos veces deja un solo favorito. */
  @Put(':contentKey')
  async add(@Req() req: RequestWithUser, @Param('contentKey') contentKey: string) {
    const key = this.key(contentKey);
    return this.prisma.favorite.upsert({
      where: { userId_contentKey: { userId: req.user.id, contentKey: key } },
      create: { userId: req.user.id, contentKey: key },
      update: {},
      select: { contentKey: true, createdAt: true },
    });
  }

  /** Idempotente: quitar uno que no existe responde igual. */
  @Delete(':contentKey')
  @HttpCode(HttpStatus.NO_CONTENT)
  async remove(@Req() req: RequestWithUser, @Param('contentKey') contentKey: string) {
    await this.prisma.favorite.deleteMany({
      where: { userId: req.user.id, contentKey: this.key(contentKey) },
    });
  }
}

