import { BadRequestException, Injectable } from '@nestjs/common';
import { Prisma } from '@prisma/client';
import { PrismaService } from '../prisma/prisma.service';
import { CreateFocusSessionDto } from './dto/focus-sessions.dto';

@Injectable()
export class FocusSessionsService {
  constructor(private readonly prisma: PrismaService) {}

  list(userId: string, limit = 50) {
    return this.prisma.focusSession.findMany({
      where: { userId },
      orderBy: { startedAt: 'desc' },
      take: limit,
    });
  }

  async create(userId: string, dto: CreateFocusSessionDto) {
    const startedAt = new Date(dto.startedAt);
    const endedAt = new Date(dto.endedAt);
    if (endedAt < startedAt) {
      throw new BadRequestException('endedAt debe ser posterior a startedAt');
    }
    if (endedAt.getTime() > Date.now() + 5 * 60_000) {
      throw new BadRequestException('endedAt no puede estar en el futuro');
    }
    if (dto.durationSeconds > dto.targetMinutes * 60) {
      throw new BadRequestException('durationSeconds supera la duración objetivo');
    }
    return this.prisma.focusSession.create({
      data: {
        userId,
        contentKey: dto.contentKey,
        mode: dto.mode,
        startedAt,
        endedAt,
        durationSeconds: dto.durationSeconds,
        targetMinutes: dto.targetMinutes,
        completed: dto.completed,
        metadata: (dto.metadata ?? undefined) as Prisma.InputJsonValue | undefined,
      },
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { Resend } from 'resend';

@Injectable()
export class MailService {
  private readonly logger = new Logger(MailService.name);
  private readonly resend = new Resend(process.env.RESEND_API_KEY);
  private readonly from = process.env.RESEND_FROM_EMAIL ?? 'CEOSMOS <onboarding@resend.dev>';

  async sendVerificationEmail(email: string, code: string): Promise<void> {
    const html = `
      <div style="background-color: #0d1117; color: #c9d1d9; font-family: sans-serif; padding: 40px; text-align: center;">
        <h1 style="color: #58a6ff;">Verifica tu cuenta CEOSMOS</h1>
        <p style="font-size: 16px;">Usa el siguiente código para verificar tu cuenta en CEOSMOS:</p>
        <div style="margin: 30px auto; padding: 20px; background-color: #161b22; border-radius: 8px; border: 1px solid #30363d; display: inline-block;">
          <h2 style="font-size: 32px; letter-spacing: 4px; margin: 0; color: #fff;">${code}</h2>
        </div>
        <p style="font-size: 14px; color: #8b949e;">Este código expira en 15 minutos.</p>
      </div>
    `;

    try {
      const { data, error } = await this.resend.emails.send({
        from: this.from,
        to: email,
        subject: 'Verifica tu cuenta CEOSMOS',
        html,
      });
      if (error) throw new Error(error.message);
      this.logger.log(`Verification email sent to ${email}: ${data?.id}`);
    } catch (error) {
      this.logger.error(`Mail error: ${error.message}`);
      throw error;
    }
  }

