import {
  Injectable,
  ForbiddenException,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateMediaDto, GetMediaQueryDto } from './dto/media.dto';

@Injectable()
export class MediaService {
  constructor(private readonly prisma: PrismaService) {}

  async getUserMedia(userId: string, query: GetMediaQueryDto) {
    return this.prisma.mediaItem.findMany({
      where: {
        userId,
        ...(query.type && { type: query.type }),
      },
      orderBy: { createdAt: 'desc' },
    });
  }

  async addMedia(userId: string, data: CreateMediaDto) {
    const totalItems = await this.prisma.mediaItem.count({
      where: { userId },
    });

    if (totalItems >= 100) {
      throw new BadRequestException('Maximum limit of 100 media items reached');
    }

    if (data.type === 'YOUTUBE') {
      const existing = await this.prisma.mediaItem.findFirst({
        where: { userId, externalId: data.externalId },
      });
      if (existing) {
        throw new BadRequestException('This YouTube video is already saved');
      }
    } else if (data.type === 'IMAGE') {
      const existing = await this.prisma.mediaItem.findFirst({
        where: { userId, url: data.url },
      });
      if (existing) {
        throw new BadRequestException('This image URL is already saved');
      }
    }

    return this.prisma.mediaItem.create({
      data: {
        userId,
        type: data.type,
        externalId: data.externalId,
        url: data.url,
        title: data.title,
        thumbnail: data.thumbnail,
      },
    });
  }

  async deleteMedia(userId: string, mediaId: string) {
    const item = await this.prisma.mediaItem.findUnique({
      where: { id: mediaId },
    });

    if (!item) {
      throw new NotFoundException('Media item not found');
    }

    if (item.userId !== userId) {
      throw new ForbiddenException('Cannot delete a media item that does not belong to you');
    }

    await this.prisma.mediaItem.delete({
      where: { id: mediaId },
    });

    return { message: 'Media item deleted successfully' };
  }
}

import { Injectable, OnModuleInit, OnModuleDestroy, Logger } from '@nestjs/common';
import { Prisma, PrismaClient } from '@prisma/client';
import { Pool, neonConfig } from '@neondatabase/serverless';
import { PrismaNeon } from '@prisma/adapter-neon';
import ws from 'ws';

/** Neon (serverless por WebSocket) en producción; PostgreSQL normal en desarrollo. */
export function isNeonUrl(url: string | undefined): boolean {
  if (!url) return false;
  try {
    return new URL(url).hostname.endsWith('.neon.tech');
  } catch {
    return false;
  }
}

function clientOptions(): Prisma.PrismaClientOptions {
  const connectionString = process.env.DATABASE_URL;
  if (!isNeonUrl(connectionString)) {
    // Base PostgreSQL local de desarrollo: motor TCP estándar de Prisma.
    return {};
  }
  neonConfig.webSocketConstructor = ws;
  return { adapter: new PrismaNeon(new Pool({ connectionString })) };
}

@Injectable()
export class PrismaService extends PrismaClient implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(PrismaService.name);

  constructor() {
    super(clientOptions());
  }

  async onModuleInit() {
    await this.$connect();
    this.logger.log(
      isNeonUrl(process.env.DATABASE_URL)
        ? 'Prisma connected to Neon PostgreSQL (via Neon Driver Adapter)'
        : 'Prisma connected to PostgreSQL (local development database)',
    );
  }

  async onModuleDestroy() {
    await this.$disconnect();
  }
}

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { createHash, randomBytes } from 'crypto';
import type { Request } from 'express';

@Injectable()
export class SessionsService {
  constructor(private readonly prisma: PrismaService) {}

  async createSession(userId: string, req: Request): Promise<string> {
    await this.prisma.session.deleteMany({ where: { userId } });

    const rawToken = randomBytes(32).toString('hex');
    const hashedToken = createHash('sha256').update(rawToken).digest('hex');

    await this.prisma.session.create({
      data: {
        userId,
        token: hashedToken,
        userAgent: req.headers['user-agent'] ?? null,
        ipAddress: (req.headers['x-forwarded-for'] as string)?.split(',')[0].trim() ?? req.ip ?? null,
        expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
      },
    });

    return rawToken;
  }

  async validateSession(sessionId: string): Promise<boolean> {
    const session = await this.prisma.session.findUnique({ where: { id: sessionId } });
    if (!session) return false;
    if (session.expiresAt < new Date()) {
      await this.prisma.session.delete({ where: { id: sessionId } });
      return false;
    }
    return true;
  }

  async deleteByUserId(userId: string): Promise<void> {
    await this.prisma.session.deleteMany({ where: { userId } });
  }
}

